companies = list_companies({})
first = list_contacts({ page: 1 })
remaining = for page in list.range(2, first.total_pages + 1) {
    result = list_contacts({ page: page })
    return result.items
}
contacts = fold acc = first.items for page in remaining { return acc + page }

# build domain -> company name map
domain_map = fold acc = {} for c in companies {
    return acc + { [c.domain]: c.name }
}

# normalize phone to E.164 if needed; return { phone, fixed }
normalize = for contact in contacts {
    phone = contact.phone if contact.phone != null else ""
    # already valid: +1 followed by exactly 10 digits
    already_ok = regex.test(phone, "^\\+1[0-9]{10}$")
    digits = regex.replace(phone, "[^0-9]", "")
    new_phone = if already_ok {
        return phone
    } else if text.length(digits) == 11 and text.starts_with(digits, "1") {
        return "+" + digits
    } else if text.length(digits) == 10 {
        return "+1" + digits
    } else if text.length(digits) > 0 {
        # try best effort: if starts with 1 and has more, take +1 and 10 digits
        return phone
    } else {
        return phone
    }
    fixed = not already_ok and new_phone != phone and regex.test(new_phone, "^\\+1[0-9]{10}$")
    # company fill
    email = contact.email if contact.email != null else ""
    parts = text.split(email, "@")
    domain = parts[1] if list.length(parts) >= 2 else ""
    company_empty = contact.company == null or contact.company == ""
    new_company = domain_map[domain] if company_empty and domain != "" and domain in domain_map else null
    company_filled = new_company != null

    needs_update = fixed or company_filled
    updated = if needs_update {
        args = { id: contact.id }
        args1 = args + ({ phone: new_phone } if fixed else {})
        args2 = args1 + ({ company: new_company } if company_filled else {})
        return update_contact(args2)
    } else {
        return null
    }
    return {
        fixed: fixed,
        company_filled: company_filled
    }
}

phones_fixed = fold acc = 0 for r in normalize {
    return acc + (1 if r.fixed else 0)
}
companies_filled = fold acc = 0 for r in normalize {
    return acc + (1 if r.company_filled else 0)
}

submit = submit_result({ answer: { phones_fixed: phones_fixed, companies_filled: companies_filled } })
return { phones_fixed, companies_filled, recorded: submit.recorded }

