        return "+1" + digits
    } else {
        return phone
    }
    fixed = (not already_ok) and new_phone != phone and regex.test(new_phone, "^\\+1[0-9]{10}$")

    email = contact.email if contact.email != null else ""
    parts = text.split(email, "@")
    domain = parts[1] if list.length(parts) >= 2 else ""
    company_empty = contact.company == null or contact.company == ""
    new_company = domain_map[domain] if company_empty and domain != "" and domain in domain_map else null
    company_filled = new_company != null

    needs_update = fixed or company_filled
    _updated = if needs_update {
        u = boundary retry 3 {
            return update_contact(
                { id: contact.id } +
                ({ phone: new_phone } if fixed else {}) +
                ({ company: new_company } if company_filled else {})
            )
        } catch err {
            return fail("UPDATE", err.message)
        }
        return u
    } else {
        return null
    }
    return {
        fixed: fixed,
        company_filled: company_filled
    }
}

phones_fixed = fold acc = 0 for r in results {
    return acc + (1 if r.fixed else 0)
}
companies_filled = fold acc = 0 for r in results {
    return acc + (1 if r.company_filled else 0)
}

submit = submit_result({ answer: { phones_fixed: phones_fixed, companies_filled: companies_filled } })
